-- 30 sismos de 2026. La alerta depende de la magnitud:
-- menor a 4.0 INFO, 4.0 a 4.9 PREV, 5.0 a 5.9 ALER, 6.0 o más EMER.
-- SIS-001, SIS-018 y SIS-026 están En seguimiento (no se pueden eliminar).

-- Un reporte de daño y un seguimiento de ejemplo para SIS-001 (requiere haber importado tipo_dano.csv)
SELECT s.id, t.id, '2026-08-18 16:10:00', 35, 'Fisuras en muros de adobe de viviendas del casco urbano de Chivay.', 'MEDIO', 'VERIFICADO'
FROM sismo s, tipo_dano t WHERE s.codigo = 'SIS-001' AND t.codigo = 'DAN-02';

SELECT id, '2026-08-19 09:00:00', 'Analista de turno', 'Se confirman daños leves en viviendas de adobe.', 'Coordinación con el gobierno local para la evaluación de viviendas.'
FROM sismo WHERE codigo = 'SIS-001';
